package com.ethk3.novaonepro.r952;
import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;
import com.ethk3.novaonepro.*;import java.nio.file.*;import java.util.*;
import com.ethk3.novaonepro.r952.CandidateCompilerR952.*;
public final class MatrixBindingsCP12Test {
 static int checks;static void ok(boolean b){checks++;if(!b)throw new AssertionError("matrix bind "+checks);}static void bad(Runnable r){checks++;try{r.run();}catch(IllegalArgumentException|IllegalStateException e){return;}throw new AssertionError("bad accepted");}
 public static void main(String[] args)throws Exception{SQLiteDatabase db=new SQLiteDatabase(args[0],args[1]);try{
  List<AtomSpecCP4> specs=new ArrayList<>();for(String line:Files.readAllLines(Path.of(args[2])))if(!line.isEmpty()){AtomSpecCP4 a=AtomSpecCP4.fromAssetLine(line);if(a.family.equals("FREQUENCY")&&a.position==1&&a.mathSpec.w==20&&a.mathSpec.digit<2)specs.add(a);}specs.sort(Comparator.comparingInt(a->a.mathSpec.digit));
  Map<String,Object> root=ModernModelContractTest.astRoot(ModelKind.SOFTMAX_LINEAR,CandidateAstR952.Family.LINEAR);List<Object> nodes=(List)root.get("nodes");List<String> hashes=new ArrayList<>();for(int i=0;i<2;i++){Map<String,Object> node=(Map)nodes.get(i);node.put("operator","ATOM");node.put("outputType",specs.get(i).outputType.equals("SCALAR")?"DOUBLE":specs.get(i).outputType);node.put("atomId",specs.get(i).atomId);node.put("parameters",Collections.emptyList());hashes.add(specs.get(i).specHash);}Collections.sort(hashes);
  Map<String,Object> fm=(Map)root.get("featureManifest");String matrixManifest=MatrixBindingsCP12.specManifest(MatrixProjectionCP12.Type.FrequencyMatrix,20,"POSITION","probabilities~0");fm.put("atomSpecHashes",hashes);fm.put("featureTypes",Arrays.asList("DOUBLE","DOUBLE"));fm.put("requiredHistory",20);fm.put("estimatedStateBytes",100000);fm.put("graphHash",CandidateAstR952.hashGraphKernelWithoutManifest(root));fm.put("matrixSpecRefs",Arrays.asList(ModernModelContractTest.map("type","FrequencyMatrix","partitionRule","CP12/20/POSITION/probabilities~0/n0","manifest",matrixManifest)));
  CandidateAstR952 ast=CandidateAstR952.parse("AST3:"+StrictCanonicalJson.write(root));Program program=CandidateCompilerR952.compile(ast,FeatureManifestR952.forAst(ast),specs);
  MatrixProjectionCP12.Spec ms=new MatrixProjectionCP12.Spec(MatrixProjectionCP12.Type.FrequencyMatrix,"position:1",20,matrixManifest);
  for(int n=10;n<30;n++){db.beginTransaction();try{MatrixSnapshotBusR952.enqueueCP12(db,ms,String.format("20260923%04d",n),n,MatrixProjectionCP12.hash("bind"+n),MatrixProjectionCP12.hash("proof"+n),new MatrixProjectionCP12.Sample(n,0,0,0,0,0,0,0,0,0),null,1);db.setTransactionSuccessful();}finally{db.endTransaction();}}
  for(int n=10;n<30;n++){MatrixSnapshotBusR952.PreparedProjectionCP12 p=MatrixSnapshotBusR952.prepareProjectionCP11(db,System.nanoTime()+20_000_000_000L);db.beginTransaction();try{ok(MatrixSnapshotBusR952.commitProjectionCP12(db,p,2));db.setTransactionSuccessful();}finally{db.endTransaction();}}
  List<Models.Draw> draws=new ArrayList<>();for(int n=10;n<30;n++){Models.Draw d=new Models.Draw();d.issue=String.format("20260923%04d",n);d.openTime=1000+n;for(int j=0;j<10;j++)d.numbers[j]=(n+j)%10+1;draws.add(d);}StringBuilder wire=new StringBuilder("R958_PIT_V2|202609230030");for(int n=29;n>=10;n--)wire.append('|').append(draws.get(n-10).issue).append(':').append(draws.get(n-10).numbersText());PITSnapshotContractR952 pit=PITSnapshotContractR952.fromFrozenHistory("202609230030",draws,V51ChecksumEngine.sha256(wire.toString()));
  Map<String,MatrixBindingsCP12.Frozen> matrices=MatrixBindingsCP12.capture(db,program,pit);ok(matrices.size()==1&&matrices.get("CP4:n0").value==1);
  Map<String,TypedAtomMoleculeGraphR930.Value> atoms=new TreeMap<>();atoms.put("CP4:n0",matrices.get("CP4:n0").atomValue(100));atoms.put("CP4:n1",TypedAtomMoleculeGraphR930.Value.present(new double[]{.1},pit.lastIssue,100,0,ModernModelContractTest.H));
  Model model=Model.fromModern(ModernModelContractTest.bound(ModernModelContractTest.sample(ModelKind.SOFTMAX_LINEAR,CandidateAstR952.Family.LINEAR),program.manifest));MemoryBudgetCP4 budget=new MemoryBudgetCP4(8L<<20);String canonical,contextHash;
  try(FrozenGraphContextCP4 ctx=FrozenGraphContextCP4.fromCapturedMatricesCP12(program,model,pit,ModernModelContractTest.H,100,atoms,Collections.emptyList(),Collections.emptyMap(),matrices,budget)){
   double[] values=program.compute(pit,ctx).values();ok(values[0]==1&&values[1]==.1&&values[2]==1&&values[3]==1);canonical=ctx.canonicalJson();contextHash=ctx.contextHash;ok(canonical.contains("SCCONTEXT2"));
   Map<String,TypedAtomMoleculeGraphR930.Value> historical=FrozenGraphContextCP4.verifyHistoricalMatricesCP12(program,StrictCanonicalJson.readContextObject(canonical),pit.targetIssue,1000);ok(historical.isEmpty()&&!MatrixHistoricalDrawCP12.requiresStoredReceiptsCP12(program));
  }ok(budget.used()==0);
  try(FrozenGraphContextCP4 replay=FrozenGraphContextCP4.fromRecipe(canonical,contextHash,ast,pit,model,budget)){ok(program.compute(pit,replay).values()[0]==1);}ok(budget.used()==0);
  Map<String,TypedAtomMoleculeGraphR930.Value> wrong=new TreeMap<>(atoms);wrong.put("CP4:n0",TypedAtomMoleculeGraphR930.Value.present(new double[]{.1},pit.lastIssue,100,0,ModernModelContractTest.H));bad(()->FrozenGraphContextCP4.fromCapturedMatricesCP12(program,model,pit,ModernModelContractTest.H,100,wrong,Collections.emptyList(),Collections.emptyMap(),matrices,budget));
  bad(()->FrozenGraphContextCP4.fromCaptured(program,model,pit,ModernModelContractTest.H,100,atoms,Collections.emptyList(),Collections.emptyMap(),budget));
  System.out.println("CP12_MATRIX_BINDINGS_PASS checks="+checks+" graphConsumed=PASS replay=PASS drawReceiptBootstrap=PASS noCurrentFallback=PASS");
 }finally{db.shutdown();}}
}
